// ============================================
// BRACKET CHALLENGE UI
// Main controller for bracket feature
// Self-contained - no external imports
// ============================================

// ============================================
// STATE
// ============================================

let bracketState = {
  settings: null,
  slots: [],
  myEntry: null,
  myPicks: new Map(),
  isAdmin: false,
  isLocked: false,
  isPaid: false,
  hasSubmitted: false,
  currentPhase: 'r32',
  championPick: null,
  championFlag: null
};

// ============================================
// BRACKET PAYMENT CONFIG
// Manual payment gateway for Bhutan/Bob/mBoB-style proof verification
// ============================================
const BRACKET_PAYMENT_CONFIG = {
  bankName: 'BOB',
  accountNumber: '203149951',
  accountHolder: 'Tandin Wangyel',
  qrImage: 'data:image/jpeg;base64,',
  storageBucket: 'bracket-payment-proofs'
};

// Holds the selected payment screenshot even if browser file input state is lost during re-render.
let bracketPaymentProofFile = null;
let bracketPaymentProofPreviewUrl = '';

function resetBracketPaymentProofSelection() {
  bracketPaymentProofFile = null;
  if (bracketPaymentProofPreviewUrl) {
    try { URL.revokeObjectURL(bracketPaymentProofPreviewUrl); } catch (_) {}
  }
  bracketPaymentProofPreviewUrl = '';
}

function getBracketEntryFee() {
  return Number(bracketState.settings?.entry_fee || 500);
}

function getBracketPaymentStatus() {
  return bracketState.myEntry?.payment_status || 'not_paid';
}

function safeHtml(value) {
  if (typeof escapeHtml === 'function') return escapeHtml(value);
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

// ============================================
// DATA FUNCTIONS (inline - no imports)
// ============================================

async function getBracketSettings() {
  const { data, error } = await supabaseClient
    .from('bracket_settings')
    .select('*')
    .single();
  if (error) throw error;
  return data;
}

async function getBracketSlots() {
  const { data, error } = await supabaseClient
    .from('bracket_slots')
    .select('*')
    .order('round', { ascending: true })
    .order('match_number', { ascending: true });
  if (error) throw error;
  return data || [];
}

async function getMyBracketEntry() {
  const user = typeof getUser === 'function' ? getUser() : supabaseClient.auth.user();
  if (!user) return null;

  const { data, error } = await supabaseClient
    .from('bracket_entries')
    .select('*')
    .eq('user_id', user.id)
    .maybeSingle();

  if (error) throw error;
  return data || null;
}

async function getMyPicks(entryId) {
  const { data, error } = await supabaseClient
    .from('bracket_picks')
    .select('*')
    .eq('entry_id', entryId);
  if (error) throw error;
  return data || [];
}

async function createBracketEntry() {
  const user = typeof getUser === 'function' ? getUser() : supabaseClient.auth.user();
  if (!user) throw new Error('Not authenticated');

  const { data, error } = await supabaseClient
    .from('bracket_entries')
    .insert({ user_id: user.id })
    .select()
    .single();
  if (error) throw error;
  return data;
}

async function uploadBracketPaymentProof(file) {
  const user = typeof getUser === 'function' ? getUser() : supabaseClient.auth.user();
  if (!user?.id) throw new Error('Please login first');
  if (!file) throw new Error('Please choose a payment screenshot');
  if (!file.type || !file.type.startsWith('image/')) throw new Error('Please upload an image screenshot');
  if (file.size > 5 * 1024 * 1024) throw new Error('Screenshot too large. Max 5MB.');

  const ext = (file.name.split('.').pop() || 'jpg').toLowerCase().replace(/[^a-z0-9]/g, '') || 'jpg';
  const path = `${user.id}/${Date.now()}-bracket-payment.${ext}`;

  const { error: uploadError } = await supabaseClient
    .storage
    .from(BRACKET_PAYMENT_CONFIG.storageBucket)
    .upload(path, file, {
      cacheControl: '3600',
      upsert: true,
      contentType: file.type
    });

  if (uploadError) throw uploadError;

  const { data: publicData } = supabaseClient
    .storage
    .from(BRACKET_PAYMENT_CONFIG.storageBucket)
    .getPublicUrl(path);

  return { path, publicUrl: publicData?.publicUrl || '' };
}

async function submitBracketPaymentProof() {
  const btn = document.getElementById('bracketPaymentSubmitBtn');
  const fileInput = document.getElementById('bracketPaymentProofInput');
  const noteInput = document.getElementById('bracketPaymentNote');
  const file = fileInput?.files?.[0] || bracketPaymentProofFile;
  const note = noteInput?.value?.trim() || '';

  if (!file) {
    const msg = 'Please attach your payment screenshot first.';
    const uploadBox = document.getElementById('bracketPaymentUploadBox');
    if (uploadBox) {
      uploadBox.classList.add('upload-error');
      uploadBox.scrollIntoView({ behavior: 'smooth', block: 'center' });
      setTimeout(() => uploadBox.classList.remove('upload-error'), 1600);
    }
    if (typeof showToast === 'function') showToast(msg, 'error');
    else alert(msg);
    return;
  }

  try {
    if (bracketState.myEntry?.payment_status === 'paid') {
      if (typeof showToast === 'function') showToast('Your bracket payment is already verified.', 'success');
      await openBracketPanel();
      return;
    }

    if (btn) {
      btn.disabled = true;
      btn.textContent = 'Uploading proof...';
    }

    const proof = await uploadBracketPaymentProof(file);

    if (btn) btn.textContent = 'Submitting for verification...';

    // Preferred secure path: SQL migration creates this RPC and only allows the
    // user to write proof fields, never to self-mark as paid.
    let savedEntry = null;
    const { data: rpcData, error: rpcError } = await supabaseClient.rpc('submit_bracket_payment_proof', {
      p_proof_url: proof.publicUrl,
      p_proof_path: proof.path,
      p_payment_note: note
    });

    if (rpcError) {
      console.warn('[Bracket] submit_bracket_payment_proof RPC failed, falling back to direct upsert:', rpcError);
      const user = typeof getUser === 'function' ? getUser() : supabaseClient.auth.user();
      if (!user?.id) throw new Error('Please login first');

      const existing = bracketState.myEntry || await getMyBracketEntry();
      const payload = {
        user_id: user.id,
        payment_status: 'pending',
        payment_proof_url: proof.publicUrl,
        payment_proof_path: proof.path,
        payment_note: note,
        payment_submitted_at: new Date().toISOString(),
        payment_rejected_reason: null,
        payment_rejected_at: null
      };

      if (existing?.id) {
        const { data, error } = await supabaseClient
          .from('bracket_entries')
          .update(payload)
          .eq('id', existing.id)
          .select()
          .single();
        if (error) throw error;
        savedEntry = data;
      } else {
        const { data, error } = await supabaseClient
          .from('bracket_entries')
          .insert(payload)
          .select()
          .single();
        if (error) throw error;
        savedEntry = data;
      }
    } else {
      savedEntry = Array.isArray(rpcData) ? rpcData[0] : rpcData;
    }

    bracketState.myEntry = savedEntry || await getMyBracketEntry();
    bracketState.isPaid = bracketState.myEntry?.payment_status === 'paid';
    bracketState.hasSubmitted = !!bracketState.myEntry?.submitted_at;

    resetBracketPaymentProofSelection();
    if (typeof showToast === 'function') showToast('Payment proof submitted. Waiting for admin verification.', 'success');
    await renderFullBracketPanel();
  } catch (err) {
    console.error('[Bracket] Payment proof submission failed:', err);
    if (typeof showToast === 'function') showToast(err.message || 'Payment proof submission failed', 'error');
    else alert(err.message || 'Payment proof submission failed');
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.textContent = 'Submit Payment Proof →';
    }
  }
}

function previewBracketPaymentProof(input) {
  const file = input?.files?.[0];
  console.log('[Bracket] Payment proof input changed:', file ? { name: file.name, type: file.type, size: file.size } : 'no file');
  const img = document.getElementById('bracketPaymentProofPreview');
  const fileName = document.getElementById('bracketPaymentProofFileName');
  const uploadBox = document.getElementById('bracketPaymentUploadBox');

  if (!file) return;

  if (!file.type || !file.type.startsWith('image/')) {
    bracketPaymentProofFile = null;
    if (input) input.value = '';
    if (typeof showToast === 'function') showToast('Please upload an image screenshot', 'error');
    return;
  }

  if (file.size > 5 * 1024 * 1024) {
    bracketPaymentProofFile = null;
    if (input) input.value = '';
    if (typeof showToast === 'function') showToast('Screenshot too large. Max 5MB.', 'error');
    return;
  }

  bracketPaymentProofFile = file;
  if (bracketPaymentProofPreviewUrl) {
    try { URL.revokeObjectURL(bracketPaymentProofPreviewUrl); } catch (_) {}
  }
  bracketPaymentProofPreviewUrl = URL.createObjectURL(file);

  if (img) {
    img.src = bracketPaymentProofPreviewUrl;
    img.classList.remove('hidden');
  }

  if (fileName) {
    fileName.textContent = file.name || 'Screenshot selected';
    fileName.classList.add('selected');
  }

  if (uploadBox) uploadBox.classList.add('has-file');

  if (typeof showToast === 'function') showToast('Screenshot attached', 'success');
}

function openBracketPaymentFilePicker() {
  const input = document.getElementById('bracketPaymentProofInput');
  if (input) input.click();
}

function clearBracketPaymentProof(event) {
  if (event) event.preventDefault();
  bracketPaymentProofFile = null;
  if (bracketPaymentProofPreviewUrl) {
    try { URL.revokeObjectURL(bracketPaymentProofPreviewUrl); } catch (_) {}
  }
  bracketPaymentProofPreviewUrl = '';

  const input = document.getElementById('bracketPaymentProofInput');
  const img = document.getElementById('bracketPaymentProofPreview');
  const fileName = document.getElementById('bracketPaymentProofFileName');
  const uploadBox = document.getElementById('bracketPaymentUploadBox');

  if (input) input.value = '';
  if (img) {
    img.src = '';
    img.classList.add('hidden');
  }
  if (fileName) {
    fileName.textContent = 'Tap to choose screenshot';
    fileName.classList.remove('selected');
  }
  if (uploadBox) uploadBox.classList.remove('has-file');
}


async function saveAllPicks(entryId, picksArray) {
  if (!picksArray.length) return;

  const { error } = await supabaseClient
    .from('bracket_picks')
    .upsert(
      picksArray.map(p => ({
        entry_id: entryId,
        slot_id: p.slot_id,
        picked_team: p.picked_team
      })),
      { onConflict: 'entry_id,slot_id' }
    );
  if (error) throw error;
}

async function submitBracket(entryId, championPick, championFlag) {
  const { error } = await supabaseClient
    .from('bracket_entries')
    .update({
      champion_pick: championPick,
      champion_pick_flag: championFlag,
      submitted_at: new Date().toISOString()
    })
    .eq('id', entryId);
  if (error) throw error;
}

function publishBracketStatusChanged(status, source = 'admin') {
  const message = {
    type: 'BRACKET_STATUS_CHANGED',
    status: String(status || ''),
    source,
    at: Date.now()
  };

  // Same-window listeners. Useful when admin controls and Home card live in the same tab.
  try {
    window.dispatchEvent(new CustomEvent('bracket-status-changed', { detail: message }));
  } catch (_) {}

  // Cross-tab listeners on the same browser/device.
  try {
    localStorage.setItem('bracket_status_value', message.status);
    localStorage.setItem('bracket_status_changed_at', String(message.at));
  } catch (_) {}

  // BroadcastChannel is instant for other open tabs on the same device.
  try {
    if ('BroadcastChannel' in window) {
      const bc = new BroadcastChannel('bracket-status');
      bc.postMessage(message);
      setTimeout(() => { try { bc.close(); } catch (_) {} }, 500);
    }
  } catch (_) {}
}

async function updateBracketStatus(status) {
  const settings = await getBracketSettings();
  const updates = { status };
  if (status === 'open') updates.opened_at = new Date().toISOString();
  if (status === 'locked') updates.locked_at = new Date().toISOString();
  if (status === 'live') updates.live_at = new Date().toISOString();
  if (status === 'completed') updates.completed_at = new Date().toISOString();

  const { error } = await supabaseClient
    .from('bracket_settings')
    .update(updates)
    .eq('id', settings.id);
  if (error) throw error;

  publishBracketStatusChanged(status, 'admin-update');
}

// ============================================
// INITIALIZATION
// ============================================

async function initBracketChallenge() {
  try {
    bracketState.settings = await getBracketSettings();
    bracketState.isLocked = isBracketLockedStatus(bracketState.settings?.status);
    if (isHiddenAdminPreviewMode()) bracketState.isLocked = false;

    // Set hidden state now; reveal happens later via applyHomeBracketStatusOverlay
    // (which fires in finally — guarantees overlay is in place before reveal).
    if (bracketState.settings?.status === 'hidden' && !canPreviewHiddenBracket()) {
      document.body.classList.add('bracket-status-hidden');
    } else {
      document.body.classList.remove('bracket-status-hidden');
    }

    setupBracketStatusListeners();
    setupHomeBracketMutationObserver();
    console.log('[Bracket] Init - status:', bracketState.settings?.status, 'isLocked:', bracketState.isLocked);
    bracketState.slots = await getBracketSlots();
    bracketState.myEntry = await getMyBracketEntry();
    bracketState.isPaid = bracketState.myEntry?.payment_status === 'paid';
    bracketState.hasSubmitted = !!bracketState.myEntry?.submitted_at;
    bracketState.championPick = bracketState.myEntry?.champion_pick;
    bracketState.championFlag = bracketState.myEntry?.champion_pick_flag;

    if (bracketState.myEntry) {
      const picks = await getMyPicks(bracketState.myEntry.id);
      picks.forEach(p => bracketState.myPicks.set(p.slot_id, p.picked_team));
    }

    const user = typeof getUser === 'function' ? getUser() : supabaseClient.auth.user();
    if (user) {
      const { data } = await supabaseClient
        .from('profiles')
        .select('role')
        .eq('id', user.id)
        .single();
      bracketState.isAdmin = data?.role === 'admin';
    }

    if (isHiddenAdminPreviewMode()) bracketState.isLocked = false;

    await renderBracketCard();
    if (shouldRunBracketCountdown()) startLiveCountdown(resolveBracketLockAt());
    else stopLiveCountdown();
  } catch (err) {
    console.error('Bracket init error:', err);
    // Don't leave the card stuck invisible if init failed midway.
    document.body.classList.add('bracket-status-ready');
  }
}


// ============================================
// LIVE STATUS REFRESH HELPERS
// ============================================

let bracketSettingsChannel = null;
let bracketStatusBroadcastChannel = null;
let bracketStatusRefreshTimer = null;

function isBracketLockedStatus(status) {
  return ['hidden', 'locked', 'live', 'completed'].includes(status);
}

function isBracketComingSoonStatus(status) {
  return !status || status === 'coming_soon';
}

function canPreviewHiddenBracket() {
  const profile = (typeof getProfile === 'function') ? getProfile() : null;

  return Boolean(
    bracketState.isAdmin === true ||
    profile?.role === 'admin' ||
    profile?.user_role === 'admin' ||
    profile?.is_admin === true ||
    ((typeof isAdmin === 'function') && isAdmin())
  );
}

function isHiddenAdminPreviewMode() {
  return bracketState.settings?.status === 'hidden' && canPreviewHiddenBracket();
}

function isEffectiveBracketLocked() {
  return isHiddenAdminPreviewMode() ? false : !!bracketState.isLocked;
}

function isEffectiveBracketPaid() {
  return isHiddenAdminPreviewMode() ? true : !!bracketState.isPaid;
}

async function refreshBracketSettingsAndRender(source = 'manual') {
  try {
    const latestSettings = await getBracketSettings();
    bracketState.settings = latestSettings;
    bracketState.isLocked = isBracketLockedStatus(latestSettings?.status);
    if (isHiddenAdminPreviewMode()) bracketState.isLocked = false;

    // Set hidden state now; reveal happens later via applyHomeBracketStatusOverlay
    // (its finally guarantees overlay is in place before reveal — no flash).
    if (latestSettings?.status === 'hidden' && !canPreviewHiddenBracket()) {
      document.body.classList.add('bracket-status-hidden');
    } else {
      document.body.classList.remove('bracket-status-hidden');
    }

    console.log('[Bracket] Status refresh from', source, {
      status: latestSettings?.status,
      isLocked: bracketState.isLocked
    });

    await renderBracketCard();
    applyHomeBracketStatusOverlay();

    // Also force the index.js-rendered home bracket card to re-fetch & re-render.
    // It maintains its own copy via getHomeBracketCopy(), so we need to nudge it
    // whenever status changes (realtime, poll, broadcast, focus, etc.).
    try {
      if (typeof window.ensureBracketChallengeHomeCard === 'function') {
        window.ensureBracketChallengeHomeCard(true);
      }
    } catch (e) {
      console.warn('[Bracket] ensureBracketChallengeHomeCard refresh failed:', e);
    }

    const panel = document.getElementById('bracket-panel');
    const panelIsOpen = panel && !panel.classList.contains('hidden');
    if (panelIsOpen) {
      await openBracketPanel();
    }
  } catch (err) {
    console.warn('[Bracket] Status refresh failed:', err);
    // Never leave the card invisible if the refresh fails — fall back to revealing
    // whatever state is currently in bracketState.
    document.body.classList.add('bracket-status-ready');
  }
}

function scheduleBracketStatusRefresh(source = 'event') {
  if (bracketStatusRefreshTimer) clearTimeout(bracketStatusRefreshTimer);
  bracketStatusRefreshTimer = setTimeout(() => {
    refreshBracketSettingsAndRender(source);
  }, 150);
}

function setupBracketStatusListeners() {
  if (window.__bracketStatusListenersReady) return;

  // If this script boots before Supabase is ready, retry instead of permanently
  // marking the listener as ready. This was one reason users had to reopen the app.
  if (typeof supabaseClient === 'undefined' || !supabaseClient) {
    setTimeout(setupBracketStatusListeners, 500);
    return;
  }

  window.__bracketStatusListenersReady = true;

  // Supabase realtime: updates every user when admin changes bracket_settings.
  // NOTE: this only works if bracket_settings is in the supabase_realtime publication AND
  // RLS allows the subscribing user to SELECT the row. If realtime is silent, the
  // polling fallback below catches changes within ~5s.
  try {
    if (supabaseClient?.channel) {
      bracketSettingsChannel = supabaseClient
        .channel('bracket-settings-watch')
        .on(
          'postgres_changes',
          { event: '*', schema: 'public', table: 'bracket_settings' },
          (payload) => {
            console.log('[Bracket] Realtime UPDATE received:', payload?.new?.status);
            bracketState.settings = payload.new;
            bracketState.isLocked = isBracketLockedStatus(payload.new?.status);
            scheduleBracketStatusRefresh('supabase-realtime');
          }
        )
        .subscribe((status) => {
          console.log('[Bracket] Realtime subscription:', status);
          if (status === 'CHANNEL_ERROR' || status === 'CLOSED' || status === 'TIMED_OUT') {
            console.warn('[Bracket] Realtime unavailable — polling fallback will keep status in sync.');
          }
        });
    }
  } catch (err) {
    console.warn('[Bracket] Realtime setup failed:', err);
  }

  // Same-browser admin panel sync fallback
  try {
    if ('BroadcastChannel' in window) {
      bracketStatusBroadcastChannel = new BroadcastChannel('bracket-status');
      bracketStatusBroadcastChannel.onmessage = (event) => {
        if (event?.data?.type === 'BRACKET_STATUS_CHANGED') {
          scheduleBracketStatusRefresh('broadcast-channel');
        }
      };
    }
  } catch (err) {
    console.warn('[Bracket] BroadcastChannel setup failed:', err);
  }

  window.addEventListener('storage', (event) => {
    if (event.key === 'bracket_status_changed_at' || event.key === 'bracket_status_value') {
      scheduleBracketStatusRefresh('local-storage');
    }
  });

  window.addEventListener('bracket-status-changed', () => {
    scheduleBracketStatusRefresh('same-window-event');
  });

  // Refresh whenever user returns to the app/tab
  window.addEventListener('focus', () => scheduleBracketStatusRefresh('window-focus'));
  document.addEventListener('visibilitychange', () => {
    if (!document.hidden) scheduleBracketStatusRefresh('tab-visible');
  });

  // Polling fallback: cheap status-only fetch every 5s while the tab is visible.
  // This guarantees every device picks up admin status changes even if realtime
  // is not enabled on the bracket_settings table. It's a single-row select on a
  // tiny table — negligible cost.
  if (!window.__bracketStatusPollTimer) {
    window.__bracketStatusPollTimer = setInterval(async () => {
      if (document.hidden) return;
      try {
        const { data, error } = await supabaseClient
          .from('bracket_settings')
          .select('status, lock_at, opened_at, locked_at, live_at, completed_at')
          .single();
        if (error) return;
        const currentKey = JSON.stringify({
          status: bracketState.settings?.status || '',
          lock_at: bracketState.settings?.lock_at || '',
          opened_at: bracketState.settings?.opened_at || '',
          locked_at: bracketState.settings?.locked_at || '',
          live_at: bracketState.settings?.live_at || '',
          completed_at: bracketState.settings?.completed_at || ''
        });
        const nextKey = JSON.stringify({
          status: data?.status || '',
          lock_at: data?.lock_at || '',
          opened_at: data?.opened_at || '',
          locked_at: data?.locked_at || '',
          live_at: data?.live_at || '',
          completed_at: data?.completed_at || ''
        });
        if (data && nextKey !== currentKey) {
          console.log('[Bracket] Polling detected settings change:', currentKey, '->', nextKey);
          scheduleBracketStatusRefresh('poll');
        }
      } catch (e) {
        // Silent — polling shouldn't surface errors to the user.
      }
    }, 5000);
  }
}



// ============================================
// HOME TAB STABLE SUSPENSE COVER
// ============================================
let homeBracketCoverTimer = null;
let homeBracketBootTimer = null;
let homeBracketLastKey = '';
let homeBracketCoverBooted = false;

function findVisibleHomeBracketCards() {
  // SAFETY: only target elements that the app has explicitly opted-in as a bracket
  // Home card. No DOM scanning by text content, no walking up from buttons, no
  // matching whole sections/articles/divs by keyword. That logic previously hid
  // parent containers and blanked the page when status flipped.
  //
  // Covers BOTH Home bracket cards:
  //   - #homeBracketLeagueCard / [data-bracket-home-card="true"]  (this file)
  //   - #home-bracket-challenge-card / .bracket-home-card          (index.js)
  const SAFE_SELECTORS = [
    '#homeBracketLeagueCard',
    '[data-bracket-home-card="true"]',
    '#home-bracket-challenge-card',
    '.bracket-home-card',
    '#bracketCard' // legacy id, retained as fallback only
  ];

  const cards = [];
  const seen = new Set();

  SAFE_SELECTORS.forEach((sel) => {
    document.querySelectorAll(sel).forEach((el) => {
      if (!el || seen.has(el)) return;
      // Skip anything inside the open bracket panel or inside a nav.
      if (el.closest?.('#bracket-panel')) return;
      if (el.closest?.('nav, .bottom-nav, .tab-bar, [role="navigation"]')) return;
      seen.add(el);
      cards.push(el);
    });
  });

  return cards;
}

function restoreHomeBracketCard(card) {
  if (!card) return;
  card.querySelectorAll(':scope > .bracket-home-status-overlay').forEach(el => el.remove());
  card.classList?.remove('has-status-overlay');
  card.removeAttribute('data-bracket-secure-covered');
  // Remove the blur class we may have added to children when the overlay was active.
  Array.from(card.children).forEach((child) => {
    child.classList?.remove('bracket-content-blurred');
  });
  ['Position','Overflow','Background','BoxShadow'].forEach(k => {
    const key = 'bracketOld' + k;
    const prop = k.charAt(0).toLowerCase() + k.slice(1).replace(/[A-Z]/g, m => '-' + m.toLowerCase());
    if (card.dataset[key] !== undefined) {
      card.style[prop] = card.dataset[key];
      delete card.dataset[key];
    }
  });
}

function scheduleHomeBracketCoverApply(delay = 80) {
  clearTimeout(homeBracketCoverTimer);
  homeBracketCoverTimer = setTimeout(() => applyHomeBracketStatusOverlay(), delay);
}

function applyHomeBracketStatusOverlay() {
  try {
  const status = bracketState.settings?.status || 'coming_soon';
  const isHidden = status === 'hidden';
  const isComingSoon = isBracketComingSoonStatus(status);
  const hasSubmitted = !!bracketState.hasSubmitted;
  const cards = findVisibleHomeBracketCards();
  const canPreviewHidden = canPreviewHiddenBracket();

  // Fully hide only real bracket cards when admin sets status to hidden.
  if (isHidden && !canPreviewHidden) {
    document.body.classList.add('bracket-status-hidden');

    cards.forEach((card) => {
      restoreHomeBracketCard(card);
      card.style.setProperty('display', 'none', 'important');
      card.classList.add('hidden');
      card.setAttribute('data-bracket-hidden-by-status', 'true');
    });

    const officialCard = document.getElementById('homeBracketLeagueCard')
                      || document.getElementById('bracketCard');
    if (officialCard) {
      officialCard.style.setProperty('display', 'none', 'important');
      officialCard.classList.add('hidden');
      officialCard.setAttribute('data-bracket-hidden-by-status', 'true');
    }

    stopLiveCountdown();
    return;
  }

  // Admin-only preview: production status stays hidden, but admin can see and open it.
  if (isHidden && canPreviewHidden) {
    document.body.classList.remove('bracket-status-hidden');
    document.querySelectorAll('[data-bracket-hidden-by-status="true"]').forEach((card) => {
      card.style.removeProperty('display');
      card.classList.remove('hidden');
      card.removeAttribute('data-bracket-hidden-by-status');
    });

    cards.forEach((card) => {
      restoreHomeBracketCard(card);
      card.style.removeProperty('display');
      card.classList.remove('hidden');
      card.removeAttribute('data-bracket-hidden-by-status');
      card.classList.add('admin-bracket-preview');

      if (!card.querySelector(':scope > .admin-preview-badge')) {
        const badge = document.createElement('div');
        badge.className = 'admin-preview-badge';
        badge.textContent = 'Admin Preview';
        card.prepend(badge);
      }
    });

    stopLiveCountdown();
    return;
  }

  // Restore cards that were hidden by bracket status only.
  document.body.classList.remove('bracket-status-hidden');
  document.querySelectorAll('[data-bracket-hidden-by-status="true"]').forEach((card) => {
    card.style.removeProperty('display');
    card.classList.remove('hidden');
    card.removeAttribute('data-bracket-hidden-by-status');
  });

  // Only coming_soon and locked use the suspense/lock cover. Live/completed are active public states.
  const shouldOverlay = isComingSoon || status === 'locked';

  if (!cards.length) {
    if (shouldRunBracketCountdown()) startLiveCountdown(resolveBracketLockAt());
    else stopLiveCountdown();
    return;
  }

  cards.forEach((card) => {
    const existing = card.querySelector(':scope > .bracket-home-status-overlay');

    if (!shouldOverlay) {
      restoreHomeBracketCard(card);
      return;
    }

    const overlayKey = `${status}:${hasSubmitted ? 'submitted' : 'not-submitted'}:${bracketState.settings?.lock_at || ''}`;
    if (existing && existing.dataset.overlayKey === overlayKey) {
      existing.style.zIndex = '2147483000';
      existing.style.display = 'flex';
      existing.style.filter = 'none';
      if (shouldRunBracketCountdown()) startLiveCountdown(resolveBracketLockAt());
      else stopLiveCountdown();
      return;
    }

    restoreHomeBracketCard(card);

    const computed = window.getComputedStyle(card);
    if (card.dataset.bracketOldPosition === undefined) card.dataset.bracketOldPosition = card.style.position || '';
    if (card.dataset.bracketOldOverflow === undefined) card.dataset.bracketOldOverflow = card.style.overflow || '';
    if (card.dataset.bracketOldBackground === undefined) card.dataset.bracketOldBackground = card.style.background || '';
    if (card.dataset.bracketOldBoxShadow === undefined) card.dataset.bracketOldBoxShadow = card.style.boxShadow || '';

    if (computed.position === 'static') card.style.position = 'relative';
    card.style.overflow = 'hidden';
    card.classList?.add('has-status-overlay');
    card.setAttribute('data-bracket-secure-covered', 'true');

    // Blur the existing card content (anything already inside the card) so the overlay
    // sits on top of a softly-blurred backdrop. The CSS .bracket-content-blurred rule
    // handles the visual; we just tag the existing direct children.
    Array.from(card.children).forEach((child) => {
      if (child.classList?.contains('bracket-home-status-overlay')) return;
      child.classList?.add('bracket-content-blurred');
    });

    const title = isComingSoon ? 'Coming Soon' : 'Entries Locked';
    const icon = isComingSoon ? '⏳' : '🔒';
    const subtitle = isComingSoon
      ? 'A new game mode will be revealed soon. Stay ready.'
      : (hasSubmitted ? 'Your picks are sealed. Leaderboard opens when scoring goes live.' : 'Entries are closed. Leaderboard opens when scoring goes live.');
    const countdownHtml = isComingSoon ? renderStatusCountdown('home-status', 'Reveals in') : '';
    const actionHtml = (!isComingSoon)
      ? `<button type="button" onclick="window.openBracketPanel()" class="bracket-overlay-action-btn">${hasSubmitted ? 'View My Picks' : 'View Leaderboard'}</button>`
      : '';

    const overlay = document.createElement('div');
    overlay.className = 'bracket-home-status-overlay bracket-status-cover-overlay';
    overlay.dataset.overlayKey = overlayKey;
    overlay.setAttribute('data-status', status);
    // Translucent panel + backdrop blur. Keep these inline so they win against any
    // stale cached CSS, but use semi-transparent backgrounds so the blur is actually visible.
    overlay.style.cssText = `
      position:absolute !important;
      inset:0 !important;
      z-index:2147483000 !important;
      display:flex !important;
      align-items:center !important;
      justify-content:center !important;
      padding:22px !important;
      box-sizing:border-box !important;
      background:${isComingSoon ? '#f8fafc' : '#f1f5f9'} !important;
      color:#1e293b !important;
      border:0 !important;
      outline:0 !important;
      box-shadow:inset 0 1px 0 rgba(255,255,255,.85), 0 16px 32px rgba(15,23,42,.08) !important;
      backdrop-filter:none !important;
      -webkit-backdrop-filter:none !important;
      pointer-events:auto !important;
    `;
    overlay.innerHTML = `
      <div class="bracket-overlay-foreground" style="position:relative !important;z-index:2147483001 !important;display:flex !important;flex-direction:column !important;align-items:center !important;justify-content:center !important;width:100% !important;max-width:290px !important;text-align:center !important;filter:none !important;opacity:1 !important;transform:none !important;backdrop-filter:none !important;-webkit-backdrop-filter:none !important;">
        <div class="bracket-overlay-icon">${icon}</div>
        <div class="bracket-overlay-title">${title}</div>
        <div class="bracket-overlay-subtitle">${subtitle}</div>
        ${countdownHtml}
        ${actionHtml}
      </div>
    `;
    card.appendChild(overlay);
  });

  if (shouldRunBracketCountdown()) startLiveCountdown(resolveBracketLockAt());
  else stopLiveCountdown();
  } finally {
    // Reveal cards ONLY now — after any overlay has been appended above.
    // Doing this in `finally` guarantees every exit path (hidden, no-cards,
    // and normal overlay-applied) reveals at the right moment, with no flash.
    document.body.classList.add('bracket-status-ready');
  }
}

function setupHomeBracketMutationObserver() {
  // The old full-body MutationObserver was causing lag and sometimes reapplied the cover to itself.
  // This lighter boot loop covers reloads, Home-tab returns, and delayed card rendering.
  if (homeBracketCoverBooted) return;
  homeBracketCoverBooted = true;

  const quickRechecks = [0, 80, 180, 350, 700, 1200, 2200, 4000, 7000, 10000];
  quickRechecks.forEach(ms => setTimeout(() => applyHomeBracketStatusOverlay(), ms));

  document.addEventListener('visibilitychange', () => {
    if (!document.hidden) scheduleBracketStatusRefresh('visibility-home-cover');
  });

  window.addEventListener('focus', () => scheduleBracketStatusRefresh('focus-home-cover'));
  window.addEventListener('hashchange', () => scheduleHomeBracketCoverApply(120));

  document.addEventListener('click', (e) => {
    // Only react to actual bottom-nav / tab-bar taps. No textContent scanning.
    const navEl = e.target?.closest?.('nav, .bottom-nav, .tab-bar, [data-tab], [role="navigation"]');
    if (!navEl) return;
    setTimeout(() => applyHomeBracketStatusOverlay(), 120);
    setTimeout(() => applyHomeBracketStatusOverlay(), 420);
  }, true);

  homeBracketBootTimer = setInterval(() => {
    const status = bracketState.settings?.status || 'coming_soon';
    const key = `${status}:${bracketState.hasSubmitted ? '1' : '0'}:${bracketState.settings?.lock_at || ''}:${findVisibleHomeBracketCards().length}`;
    if (key !== homeBracketLastKey) {
      homeBracketLastKey = key;
      applyHomeBracketStatusOverlay();
    }
  }, 1600);
}

