function closeBracketHowItWorks() {
  document.getElementById('bpHowItWorksModal')?.remove();
}

async function renderFullBracketPanel() {
  const container = document.getElementById('bracket-content');
  if (!container) return;

  const isHiddenAdminPreview = isHiddenAdminPreviewMode();
  const isLocked = isHiddenAdminPreview ? false : bracketState.isLocked;
  const isPaid = isHiddenAdminPreview ? true : bracketState.isPaid;
  const hasSubmitted = bracketState.hasSubmitted;
  const leaderboardVisible = isHiddenAdminPreview ? false : canShowBracketLeaderboard();

  if (leaderboardVisible && (!isPaid || !hasSubmitted) && bracketState.currentPhase !== 'leaderboard') {
    bracketState.currentPhase = 'leaderboard';
  }

  if (!leaderboardVisible && bracketState.currentPhase === 'leaderboard') {
    bracketState.currentPhase = 'r32';
  }

  console.log('[Bracket] renderFullBracketPanel:', {
    status: bracketState.settings?.status,
    isLocked,
    isPaid,
    hasSubmitted,
    leaderboardVisible,
    currentPhase: bracketState.currentPhase
  });

  // COMING SOON → show the bracket preview blurred with a clear message.
  if (isBracketComingSoonStatus(bracketState.settings?.status)) {
    container.innerHTML = renderBlurredBracketStatusPanel('coming_soon');
    startLiveCountdown(resolveBracketLockAt());
    return;
  }

  // Before lock, bracket remains paid/private.
  if (!leaderboardVisible && !isPaid) {
    container.innerHTML = renderPaymentGate();
    return;
  }

  // Before lock, unpaid/non-submitted users should not see other brackets.
  if (!leaderboardVisible && isLocked && !hasSubmitted) {
    container.innerHTML = renderBlurredBracketStatusPanel('locked_no_entry');
    return;
  }

  const canViewPrivateBracket = isPaid && (hasSubmitted || !isLocked);
  const showPrivateTabs = canViewPrivateBracket;

  container.innerHTML = `
    ${renderBracketFantasyHero()}
    ${isHiddenAdminPreview ? `
      <div class="bp-admin-preview-strip">
        <strong>Admin Preview</strong> · Hidden from players. You can view and test the bracket while production status stays hidden.
      </div>
    ` : ''}
    <div class="bp-header">
      <div class="bp-phase-tabs">
        ${showPrivateTabs ? `
          <button class="bp-tab ${bracketState.currentPhase === 'r32' ? 'active' : ''}" onclick="switchBracketPhase('r32')">R32</button>
          <button class="bp-tab ${bracketState.currentPhase === 'r16' ? 'active' : ''}" onclick="switchBracketPhase('r16')">R16</button>
          <button class="bp-tab ${bracketState.currentPhase === 'qf' ? 'active' : ''}" onclick="switchBracketPhase('qf')">QF</button>
          <button class="bp-tab ${bracketState.currentPhase === 'sf' ? 'active' : ''}" onclick="switchBracketPhase('sf')">SF</button>
          <button class="bp-tab ${bracketState.currentPhase === 'final' ? 'active' : ''}" onclick="switchBracketPhase('final')">Final</button>
          <button class="bp-tab ${bracketState.currentPhase === 'champion' ? 'active' : ''}" onclick="switchBracketPhase('champion')">${bpIcon('crown','bp-tab-icon')} Champion</button>
          <button class="bp-tab bp-tab-overview ${bracketState.currentPhase === 'overview' ? 'active' : ''}" onclick="switchBracketPhase('overview')">View Bracket</button>
        ` : ''}
        ${leaderboardVisible ? `
          <button class="bp-tab bp-tab-leaderboard ${bracketState.currentPhase === 'leaderboard' ? 'active' : ''}" onclick="switchBracketPhase('leaderboard')">Leaderboard</button>
        ` : ''}
      </div>
      ${!isLocked && canViewPrivateBracket ? `
        <div class="bp-actions">
          <button class="bp-btn-secondary" onclick="saveBracketPicks()">Save Draft</button>
          <button class="bp-btn-primary" onclick="submitFinalBracket()">Submit Bracket</button>
        </div>
      ` : ''}
    </div>

    <div class="bp-phase-content" id="bpPhaseContent">
      ${renderPhaseContent(bracketState.currentPhase)}
    </div>

    ${bracketState.currentPhase !== 'leaderboard' ? renderBracketSummaryBar() : ''}
    ${!isLocked && canViewPrivateBracket ? renderBracketDeadlineStrip() : ''}

    ${hasSubmitted ? `
      <div class="bp-submitted-banner" style="
        background: #d1fae5;
        color: #059669;
        padding: 12px 16px;
        border-radius: 12px;
        margin-top: 16px;
        font-size: 14px;
        font-weight: 600;
        text-align: center;
      ">
        ✓ Your bracket is submitted${isLocked ? ' and locked' : ''}
      </div>
    ` : ''}
  `;

  if (bracketState.currentPhase === 'leaderboard') {
    await renderBracketLeaderboardIntoView();
  }
}

function switchBracketPhase(phase) {
  bracketState.currentPhase = phase;
  renderFullBracketPanel();
}

function renderPhaseContent(phase) {
  if (phase === 'leaderboard') {
    return renderBracketLeaderboardSkeleton();
  }

  if (phase === 'overview') {
    return renderBracketOverviewContent();
  }

  if (phase === 'champion') {
    return renderChampionPhase();
  }

  const slots = bracketState.slots.filter(s => s.round === phase);
  const phaseNames = {
    r32: 'Round of 32', r16: 'Round of 16', qf: 'Quarter-Finals',
    sf: 'Semi-Finals', final: 'Final'
  };
  const completed = getCompletedPickCount();
  const total = getExpectedPickCount();
  const pct = getBracketCompletionPct();

  return `
    <div class="bp-phase-header bp-phase-header-compact">
      <div class="bp-phase-title-wrap">
        <div class="bp-phase-kicker">${completed} / ${total} picks completed</div>
        <h3>${phaseNames[phase]}</h3>
      </div>
      <div class="bp-phase-tools">
        <span class="bp-points-badge">${getRoundPoints(phase)} pts per correct pick</span>
        <button type="button" class="bp-view-bracket-btn" onclick="switchBracketPhase('overview')">View Bracket</button>
      </div>
    </div>
    <div class="bp-phase-progress-row" aria-label="Bracket progress">
      <div class="bp-phase-progress-text"><b>${completed}</b> / ${total} completed</div>
      <div class="bp-phase-progress-bar"><span style="width:${pct}%"></span></div>
    </div>
    <div class="bp-matches">
      ${slots.map(slot => renderMatchCard(slot)).join('')}
    </div>
  `;
}

function renderBracketOverviewContent() {
  const rounds = [
    ['r32', 'Round of 32'],
    ['r16', 'Round of 16'],
    ['qf', 'Quarter-finals'],
    ['sf', 'Semi-finals'],
    ['final', 'Final']
  ];
  const champName = bracketState.championPick || 'Champion';
  const champFlag = bracketState.championFlag || '';

  const roundColumns = rounds.map(([round, label]) => {
    const slots = bracketState.slots.filter(s => s.round === round);
    return `
      <div class="bp-overview-col">
        <div class="bp-overview-col-title">${label}</div>
        <div class="bp-overview-slots">
          ${slots.map(slot => {
            const pick = bracketState.myPicks.get(slot.id);
            const pickName = pick === 'team_a' ? (slot.team_a || 'TBD') : pick === 'team_b' ? (slot.team_b || 'TBD') : 'No pick';
            const pickFlag = pick === 'team_a' ? (slot.team_a_flag || '🏳️') : pick === 'team_b' ? (slot.team_b_flag || '🏳️') : '—';
            return `
              <div class="bp-overview-match ${pick ? 'picked' : ''}">
                <small>${bpEscapeHtml(slot.slot_label || '')}</small>
                <span>${pick ? bpTeamFlagHtml(pickName, pickFlag, 18) : bpIcon('flag','bp-mini-empty-flag')} ${bpEscapeHtml(pickName)}</span>
              </div>
            `;
          }).join('')}
        </div>
      </div>
    `;
  }).join('');

  return `
    <div class="bp-phase-header bp-phase-header-compact">
      <div class="bp-phase-title-wrap">
        <div class="bp-phase-kicker">Bracket overview</div>
        <h3>Your Knockout Path</h3>
      </div>
      <button type="button" class="bp-view-bracket-btn active" onclick="switchBracketPhase('r32')">Back to Picks</button>
    </div>
    <div class="bp-overview-scroll" aria-label="Full bracket overview">
      <div class="bp-overview-board">
        ${roundColumns}
        <div class="bp-overview-col bp-overview-champion-col">
          <div class="bp-overview-col-title">Champion</div>
          <div class="bp-overview-champion">
            <div class="bp-overview-champion-label">CHAMPION</div>
            <div class="bp-overview-champion-flag">${bracketState.championPick ? bpTeamFlagHtml(champName, champFlag, 44) : bpIcon('crown','bp-overview-crown')}</div>
            <strong>${bpEscapeHtml(champName)}</strong>
            <span>${bpIcon('cup','bp-overview-cup')}</span>
          </div>
        </div>
      </div>
    </div>
  `;
}

function renderMatchCard(slot) {
  const myPick = bracketState.myPicks.get(slot.id);
  const hasWinner = slot.winner !== '';
  const isCorrect = myPick && myPick === slot.winner;
  const isLocked = isEffectiveBracketLocked();

  let teamAClass = '';
  let teamBClass = '';

  if (hasWinner && myPick) {
    if (myPick === 'team_a') teamAClass = isCorrect ? 'correct' : 'wrong';
    if (myPick === 'team_b') teamBClass = isCorrect ? 'correct' : 'wrong';
  } else if (myPick) {
    if (myPick === 'team_a') teamAClass = 'selected';
    if (myPick === 'team_b') teamBClass = 'selected';
  }

  const canPick = !isLocked && !hasWinner && slot.team_a && slot.team_b;

  return `
    <div class="bp-match" data-slot="${slot.id}">
      <div class="bp-match-label">${slot.slot_label}</div>
      <div class="bp-match-teams">
        <button class="bp-team ${teamAClass} ${canPick ? 'pickable' : ''}"
                onclick="pickTeam('${slot.id}', 'team_a')"
                ${!canPick ? 'disabled' : ''}>
          <span class="bp-flag">${bpTeamFlagHtml(slot.team_a, slot.team_a_flag, 26)}</span>
          <span class="bp-team-name">${slot.team_a || 'TBD'}</span>
          ${hasWinner && slot.winner === 'team_a' ? '<span class="bp-winner-mark">✓</span>' : ''}
        </button>
        <div class="bp-vs">VS</div>
        <button class="bp-team ${teamBClass} ${canPick ? 'pickable' : ''}"
                onclick="pickTeam('${slot.id}', 'team_b')"
                ${!canPick ? 'disabled' : ''}>
          <span class="bp-flag">${bpTeamFlagHtml(slot.team_b, slot.team_b_flag, 26)}</span>
          <span class="bp-team-name">${slot.team_b || 'TBD'}</span>
          ${hasWinner && slot.winner === 'team_b' ? '<span class="bp-winner-mark">✓</span>' : ''}
        </button>
      </div>
      <div class="bp-pick-footer">
        ${myPick ? `<span class="bp-pick-label">${bpIcon('shield','bp-pick-icon')} Your pick: <b>${myPick === 'team_a' ? bpEscapeHtml(slot.team_a || 'TBD') : bpEscapeHtml(slot.team_b || 'TBD')}</b></span>` : '<span class="bp-pick-label muted">— No pick</span>'}
        ${hasWinner ? `
          <span class="bp-result">
            ${isCorrect ? `<span class="bp-result-correct">✓ +${slot.points_value} pts</span>` : ''}
            ${myPick && !isCorrect ? '<span class="bp-result-wrong">✗ Wrong</span>' : ''}
            ${!myPick ? '<span class="bp-result-missed">Missed</span>' : ''}
          </span>
        ` : `<span class="bp-lock-state">${canPick ? 'Make your pick' : 'Pick locked 🔒'}</span>`}
      </div>
    </div>
  `;
}

function renderChampionPhase() {
  const isLocked = bracketState.isLocked;
  const hasPick = !!bracketState.championPick;
  const teamOptions = getChampionTeamOptions();
  const optionCount = teamOptions.length;

  return `
    <div class="bp-phase-header">
      <h3>Champion Pick</h3>
      <span class="bp-points-badge">15 pts bonus</span>
    </div>

    <div class="bp-champion-area bp-champion-modal-entry">
      <div class="bp-champion-hero-card ${hasPick ? 'has-pick' : ''}">
        <div class="bp-champion-hero-icon">${hasPick ? bpTeamFlagHtml(bracketState.championPick, bracketState.championFlag, 46) : bpIcon('crown','bp-champion-empty-crown')}</div>
        <div class="bp-champion-hero-copy">
          <div class="bp-champion-kicker">Final bonus pick</div>
          <h4>${hasPick ? bpEscapeHtml(bracketState.championPick) : 'Choose your World Cup champion'}</h4>
          <p>
            ${hasPick
              ? 'Your champion is saved in this draft. Submit before lock to make it final.'
              : optionCount
                ? `${optionCount} teams available from the Round of 32 slots.`
                : 'Teams will appear here after the admin adds the Round of 32 teams.'}
          </p>
        </div>
      </div>

      ${!isLocked ? `
        <button class="bp-champion-open-btn" onclick="openChampionPickerModal()">
          <span>${hasPick ? 'Change Champion' : 'Pick Champion'}</span>
          <span>→</span>
        </button>
      ` : hasPick ? `
        <div class="bp-champion-locked-note">🔒 Champion pick locked</div>
      ` : `
        <div class="bp-champion-locked-note">No champion pick submitted</div>
      `}

      ${hasPick && !isLocked ? `
        <button class="bp-champion-clear-btn" onclick="clearChampion()">Clear champion pick</button>
      ` : ''}
    </div>
  `;
}

function getChampionTeamOptions() {
  const teams = new Map();
  const r32Slots = bracketState.slots.filter(slot => slot.round === 'r32');

  r32Slots.forEach(slot => {
    addChampionTeamOption(teams, slot.team_a, slot.team_a_flag);
    addChampionTeamOption(teams, slot.team_b, slot.team_b_flag);
  });

  // Fallback: if an older setup only has later-round teams filled, still allow a pick.
  if (!teams.size) {
    bracketState.slots.forEach(slot => {
      addChampionTeamOption(teams, slot.team_a, slot.team_a_flag);
      addChampionTeamOption(teams, slot.team_b, slot.team_b_flag);
    });
  }

  return Array.from(teams.values()).sort((a, b) => a.name.localeCompare(b.name));
}

function addChampionTeamOption(teams, name, flag) {
  const cleanName = String(name || '').trim();
  if (!isUsableChampionTeamName(cleanName)) return;

  const key = cleanName.toLowerCase();
  if (!teams.has(key)) {
    teams.set(key, {
      name: cleanName,
      flag: String(flag || '').trim() || '🏳️'
    });
  }
}

function isUsableChampionTeamName(name) {
  if (!name) return false;
  const lowered = name.toLowerCase();
  return !['tbd', 'to be decided', 'pending', 'n/a', '-'].includes(lowered);
}

function openChampionPickerModal() {
  if (isBracketComingSoonStatus(bracketState.settings?.status) || isEffectiveBracketLocked()) return;

  closeChampionPickerModal();

  const teams = getChampionTeamOptions();
  const modal = document.createElement('div');
  modal.id = 'bpChampionModal';
  modal.className = 'bp-champion-modal-backdrop';
  modal.innerHTML = `
    <div class="bp-champion-modal" role="dialog" aria-modal="true" aria-labelledby="bpChampionModalTitle">
      <div class="bp-champion-modal-handle"></div>
      <div class="bp-champion-modal-header">
        <div>
          <div class="bp-champion-kicker">Champion Picker</div>
          <h3 id="bpChampionModalTitle">Select your champion</h3>
          <p>${teams.length ? 'Search and pick one team. You can change it until the bracket locks.' : 'No teams are available yet.'}</p>
        </div>
        <button type="button" class="bp-champion-modal-close" aria-label="Close champion picker">×</button>
      </div>

      ${teams.length ? `
        <div class="bp-champion-search-wrap">
          <span>🔎</span>
          <input id="bpChampionSearch" type="search" placeholder="Search team..." autocomplete="off" />
        </div>
        <div class="bp-champion-modal-list" id="bpChampionList">
          ${teams.map(team => `
            <button type="button"
                    class="bp-champion-modal-option ${team.name === bracketState.championPick ? 'selected' : ''}"
                    data-team="${bpEscapeAttr(team.name)}"
                    data-flag="${bpEscapeAttr(team.flag)}"
                    data-search="${bpEscapeAttr(team.name.toLowerCase())}">
              <span class="bp-champion-option-flag">${bpEscapeHtml(team.flag)}</span>
              <span class="bp-champion-option-name">${bpEscapeHtml(team.name)}</span>
              <span class="bp-champion-option-check">${team.name === bracketState.championPick ? '✓' : ''}</span>
            </button>
          `).join('')}
        </div>
        <div class="bp-champion-empty-search hidden" id="bpChampionEmptySearch">
          No team found. Try another name.
        </div>
      ` : `
        <div class="bp-champion-modal-empty">
          <div>🏳️</div>
          <h4>Teams not added yet</h4>
          <p>Once the admin updates the Round of 32 teams, they will appear here automatically.</p>
        </div>
      `}
    </div>
  `;

  document.body.appendChild(modal);
  document.body.classList.add('bp-champion-modal-open');

  const closeBtn = modal.querySelector('.bp-champion-modal-close');
  closeBtn?.addEventListener('click', closeChampionPickerModal);

  modal.addEventListener('click', (event) => {
    if (event.target === modal) closeChampionPickerModal();
  });

  modal.querySelectorAll('.bp-champion-modal-option').forEach(button => {
    button.addEventListener('click', () => {
      pickChampion(button.dataset.team || '', button.dataset.flag || '');
    });
  });

  const searchInput = modal.querySelector('#bpChampionSearch');
  searchInput?.addEventListener('input', () => filterChampionOptions(searchInput.value));

  document.addEventListener('keydown', handleChampionModalKeydown);
  setTimeout(() => searchInput?.focus(), 120);
}

function closeChampionPickerModal() {
  const modal = document.getElementById('bpChampionModal');
  if (modal) modal.remove();
  document.body.classList.remove('bp-champion-modal-open');
  document.removeEventListener('keydown', handleChampionModalKeydown);
}

function handleChampionModalKeydown(event) {
  if (event.key === 'Escape') closeChampionPickerModal();
}

function filterChampionOptions(query) {
  const modal = document.getElementById('bpChampionModal');
  if (!modal) return;

  const normalizedQuery = String(query || '').trim().toLowerCase();
  const options = Array.from(modal.querySelectorAll('.bp-champion-modal-option'));
  let visibleCount = 0;

  options.forEach(option => {
    const haystack = option.dataset.search || '';
    const shouldShow = !normalizedQuery || haystack.includes(normalizedQuery);
    option.classList.toggle('hidden', !shouldShow);
    if (shouldShow) visibleCount += 1;
  });

  const empty = modal.querySelector('#bpChampionEmptySearch');
  empty?.classList.toggle('hidden', visibleCount > 0);
}

function bpEscapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function bpEscapeAttr(value) {
  return bpEscapeHtml(value).replace(/`/g, '&#96;');
}


