    crown: `<svg viewBox="0 0 64 64" aria-hidden="true"><defs><linearGradient id="bpCrownGold" x1="9" y1="12" x2="55" y2="52"><stop stop-color="#FDE68A"/><stop offset=".5" stop-color="#F59E0B"/><stop offset="1" stop-color="#92400E"/></linearGradient></defs><path d="M10 23l12 11 10-19 10 19 12-11-5 26H15L10 23Z" fill="url(#bpCrownGold)"/><path d="M17 53h30" stroke="#FDE68A" stroke-width="5" stroke-linecap="round"/><circle cx="32" cy="15" r="4" fill="#FFF7CC"/></svg>`,
    shield: `<svg viewBox="0 0 64 64" aria-hidden="true"><defs><linearGradient id="bpShieldPurple" x1="12" y1="8" x2="52" y2="56"><stop stop-color="#C084FC"/><stop offset=".52" stop-color="#7C3AED"/><stop offset="1" stop-color="#1E1B4B"/></linearGradient></defs><path d="M32 6l22 8v16c0 15-9 24-22 30C19 54 10 45 10 30V14l22-8Z" fill="url(#bpShieldPurple)"/><path d="M32 13v36" stroke="#E9D5FF" stroke-width="3" opacity=".45"/><path d="M19 21h26" stroke="#fff" stroke-width="3" stroke-linecap="round" opacity=".45"/></svg>`,
