    flag: `<svg viewBox="0 0 64 64" aria-hidden="true"><defs><linearGradient id="bpFlagPurple" x1="12" y1="8" x2="52" y2="56"><stop stop-color="#A78BFA"/><stop offset="1" stop-color="#312E81"/></linearGradient></defs><path d="M18 52V11" stroke="#E9D5FF" stroke-width="5" stroke-linecap="round"/><path d="M21 12h28l-5 10 5 10H21V12Z" fill="url(#bpFlagPurple)"/><path d="M25 18h14" stroke="#fff" stroke-width="3" stroke-linecap="round" opacity=".55"/></svg>`,
    target: `<svg viewBox="0 0 64 64" aria-hidden="true"><defs><linearGradient id="bpTargetPurple" x1="9" y1="8" x2="55" y2="56"><stop stop-color="#C084FC"/><stop offset="1" stop-color="#7C3AED"/></linearGradient></defs><circle cx="32" cy="32" r="22" fill="none" stroke="url(#bpTargetPurple)" stroke-width="6"/><circle cx="32" cy="32" r="11" fill="none" stroke="#F5D0FE" stroke-width="5"/><path d="M32 32l17-17" stroke="#FBBF24" stroke-width="5" stroke-linecap="round"/><path d="M49 15h8v8" fill="none" stroke="#FBBF24" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg>`
