const BP_FLAG_CODE_MAP = {
  argentina:'ar', brazil:'br', canada:'ca', mexico:'mx', usa:'us', 'united states':'us', france:'fr', germany:'de', spain:'es', portugal:'pt', england:'gb-eng', netherlands:'nl', belgium:'be', italy:'it', croatia:'hr', uruguay:'uy', japan:'jp', 'south korea':'kr', korea:'kr', 'korea republic':'kr', australia:'au', morocco:'ma', senegal:'sn', switzerland:'ch', denmark:'dk', sweden:'se', poland:'pl', serbia:'rs', austria:'at', wales:'gb-wls', scotland:'gb-sct', 'northern ireland':'gb-nir', ireland:'ie', 'republic of ireland':'ie', qatar:'qa', iran:'ir', 'saudi arabia':'sa', ghana:'gh', nigeria:'ng', cameroon:'cm', egypt:'eg', tunisia:'tn', algeria:'dz', 'new zealand':'nz'
};

function bpNormalizeFlagCode(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  if (/^[a-z]{2}$/i.test(raw)) return raw.toLowerCase();
  if (/^gb-(eng|sct|wls|nir)$/i.test(raw)) return raw.toLowerCase();
  return BP_FLAG_CODE_MAP[raw.toLowerCase()] || '';
}

function bpLooksLikeEmojiFlag(value) {
  const v = String(value || '').trim();
  return /[\u{1F1E6}-\u{1F1FF}]{2}/u.test(v) || /[🏴🏳️🇦-🇿]/u.test(v);
}

function bpTeamFlagHtml(teamName, storedFlag = '', size = 26) {
  if (typeof window.flagHtml === 'function') {
    try { return window.flagHtml(teamName || storedFlag || 'TBD', size); } catch (_) {}
  }

  const safeTeam = bpEscapeAttr(teamName || storedFlag || 'Team');
  const stored = String(storedFlag || '').trim();
  const name = String(teamName || '').trim();
  const lowerName = name.toLowerCase();

  if (!name || /^(tbd|tbc|to be determined|to be confirmed)$/i.test(name)) {
    return `<span class="bp-flag-placeholder" title="To be determined">${bpIcon('flag','bp-flag-placeholder-icon')}</span>`;
  }

  const code = bpNormalizeFlagCode(stored) || bpNormalizeFlagCode(name);
  if (code) {
    return `<img src="https://flagcdn.com/w80/${bpEscapeAttr(code)}.png" alt="${safeTeam}" class="bp-flag-img" loading="lazy" onerror="this.replaceWith(document.createTextNode('🏳️'))">`;
  }

  if (bpLooksLikeEmojiFlag(stored)) return `<span class="bp-flag-emoji" title="${safeTeam}">${bpEscapeHtml(stored)}</span>`;
  return `<span class="bp-flag-emoji" title="${safeTeam}">🏳️</span>`;
}


