// ============================================
// INTERACTION HANDLERS
// ============================================

function pickTeam(slotId, team) {
  if (isBracketComingSoonStatus(bracketState.settings?.status) || isEffectiveBracketLocked()) return;

  const current = bracketState.myPicks.get(slotId);
  if (current === team) {
    bracketState.myPicks.delete(slotId);
  } else {
    bracketState.myPicks.set(slotId, team);
  }

  renderFullBracketPanel();
}

function pickChampion(name, flag) {
  if (isBracketComingSoonStatus(bracketState.settings?.status) || isEffectiveBracketLocked()) return;
  const cleanName = String(name || '').trim();
  if (!cleanName) return;

  bracketState.championPick = cleanName;
  bracketState.championFlag = String(flag || '').trim();

  closeChampionPickerModal();
  renderFullBracketPanel();
  bpShowToast('Champion pick selected!', 'success');
}

function clearChampion() {
  if (isBracketComingSoonStatus(bracketState.settings?.status) || isEffectiveBracketLocked()) return;
  bracketState.championPick = null;
  bracketState.championFlag = null;
  closeChampionPickerModal();
  renderFullBracketPanel();
}

async function saveBracketPicks() {
  try {
    // Double-check live status before allowing writes.
    bracketState.settings = await getBracketSettings();
    bracketState.isLocked = isBracketLockedStatus(bracketState.settings?.status);
    if (isHiddenAdminPreviewMode()) bracketState.isLocked = false;

    if (isBracketComingSoonStatus(bracketState.settings?.status)) {
      await renderFullBracketPanel();
      throw new Error('Bracket is not open yet');
    }

    if (isEffectiveBracketLocked()) {
      await renderFullBracketPanel();
      throw new Error('Bracket is already locked');
    }

    const user = typeof getUser === 'function' ? getUser() : supabaseClient.auth.user();
    if (!user) throw new Error('Not logged in');

    if (!bracketState.myEntry) {
      bracketState.myEntry = await createBracketEntry();
    }

    const picksArray = Array.from(bracketState.myPicks.entries()).map(([slot_id, picked_team]) => ({
      slot_id,
      picked_team
    }));

    if (picksArray.length) {
      await saveAllPicks(bracketState.myEntry.id, picksArray);
    }

    if (bracketState.championPick) {
      await supabaseClient
        .from('bracket_entries')
        .update({
          champion_pick: bracketState.championPick,
          champion_pick_flag: bracketState.championFlag
        })
        .eq('id', bracketState.myEntry.id);
    }

    bpShowToast('Draft saved!', 'success');
  } catch (err) {
    bpShowToast('Save failed: ' + err.message, 'error');
  }
}

async function submitFinalBracket() {
  bracketState.settings = await getBracketSettings();
  bracketState.isLocked = isBracketLockedStatus(bracketState.settings?.status);

  if (isBracketComingSoonStatus(bracketState.settings?.status)) {
    await renderFullBracketPanel();
    bpShowToast('Bracket is not open yet.', 'warning');
    return;
  }

  if (isEffectiveBracketLocked()) {
    await renderFullBracketPanel();
    bpShowToast('Bracket is already locked.', 'warning');
    return;
  }

  if (!bracketState.championPick) {
    bpShowToast('Please pick a champion first!', 'warning');
    switchBracketPhase('champion');
    return;
  }

  const r32Slots = bracketState.slots.filter(s => s.round === 'r32').length;
  const myR32Picks = Array.from(bracketState.myPicks.keys()).filter(id => {
    const slot = bracketState.slots.find(s => s.id === id);
    return slot?.round === 'r32';
  }).length;

  if (myR32Picks < r32Slots) {
    if (!confirm(`You've only picked ${myR32Picks}/${r32Slots} Round of 32 matches. Submit anyway?`)) return;
  }

  if (!confirm('Submit your bracket? You cannot edit after submission.')) return;

  try {
    await saveBracketPicks();
    await submitBracket(bracketState.myEntry.id, bracketState.championPick, bracketState.championFlag);
    bracketState.hasSubmitted = true;
    renderBracketCard();
    renderFullBracketPanel();
    bpShowToast('Bracket submitted successfully!', 'success');
  } catch (err) {
    bpShowToast('Submit failed: ' + err.message, 'error');
  }
}

// ============================================
// HELPERS
// ============================================

function getRoundPoints(round) {
  const points = { r32: 2, r16: 3, qf: 5, sf: 8, final: 12, champion: 15 };
  return points[round] || 0;
}

function bpShowToast(message, type) {
  if (typeof showNotification === 'function') {
    showNotification(message, type);
  } else {
    console.log(`[${type}] ${message}`);
  }

  const toast = document.createElement('div');
  toast.style.cssText = `
    position:fixed;bottom:80px;left:50%;transform:translateX(-50%);
    padding:12px 24px;border-radius:12px;font-size:14px;font-weight:600;
    z-index:1000;animation:bpToastIn 0.3s ease;
    ${type === 'success' ? 'background:#22c55e;color:white;' : ''}
    ${type === 'error' ? 'background:#ef4444;color:white;' : ''}
    ${type === 'warning' ? 'background:#f59e0b;color:white;' : ''}
    ${type === 'info' ? 'background:#1e293b;color:white;' : ''}
  `;
  toast.textContent = message;
  document.body.appendChild(toast);
  setTimeout(() => toast.remove(), 3000);
}

// Add toast animation
const toastStyle = document.createElement('style');
toastStyle.textContent = `
  @keyframes bpToastIn {
    from { opacity:0;transform:translateX(-50%) translateY(20px); }
    to { opacity:1;transform:translateX(-50%) translateY(0); }
  }
`;
document.head.appendChild(toastStyle);


// ============================================
// BRACKET LEADERBOARD UI
// Public only after bracket is locked/live/completed
// ============================================

function canShowBracketLeaderboard() {
  const status = bracketState.settings?.status || 'coming_soon';
  return ['locked', 'live', 'completed'].includes(status);
}

async function getBracketLeaderboard() {
  const { data, error } = await supabaseClient
    .from('bracket_leaderboard')
    .select('*')
    .order('total_points', { ascending: false });

  if (error) throw error;
  return data || [];
}

function getCurrentUserIdSafe() {
  try {
    const user = typeof getUser === 'function' ? getUser() : supabaseClient.auth.user();
    return user?.id || null;
  } catch (_) {
    return null;
  }
}

function getLeaderboardPlayerName(row) {
  return row.full_name || row.name || row.player_name || row.display_name || row.username || 'Player';
}

function getLeaderboardUserId(row) {
  return row.user_id || row.profile_id || row.id || null;
}

function getLeaderboardChampion(row) {
  return row.champion_pick || row.champion || row.champion_team || row.winner_pick || '—';
}

function getLeaderboardChampionFlag(row) {
  return row.champion_pick_flag || row.champion_flag || row.flag || '🏳️';
}

function getLeaderboardCorrectPicks(row) {
  return Number(row.correct_picks ?? row.correct_count ?? row.correct ?? 0);
}

function getLeaderboardTotalPoints(row) {
  return Number(row.total_points ?? row.points ?? row.score ?? 0);
}

function getLeaderboardRank(row, index) {
  return Number(row.rank ?? row.position ?? row.leaderboard_rank ?? index + 1);
}

function getRankMedal(rank) {
  if (rank === 1) return '🥇';
  if (rank === 2) return '🥈';
  if (rank === 3) return '🥉';
  return `#${rank}`;
}

function renderBracketLeaderboardSkeleton() {
  return `
    <div class="bp-leaderboard-wrap">
      <div class="bp-leaderboard-hero">
        <div>
          <div class="bp-leaderboard-kicker">Public after lock</div>
          <h3>Bracket Leaderboard</h3>
          <p>Champion picks, correct picks and bracket points only.</p>
        </div>
        <button class="bp-refresh-btn" onclick="renderBracketLeaderboardIntoView()">Refresh</button>
      </div>
      <div class="bp-leaderboard-card">
        <div class="bp-leaderboard-loading">Loading leaderboard...</div>
      </div>
    </div>
  `;
}

async function renderBracketLeaderboardIntoView() {
  const target = document.getElementById('bpPhaseContent');
  if (!target) return;

  if (!canShowBracketLeaderboard()) {
    target.innerHTML = renderBracketLeaderboardLockedState();
    return;
  }

  target.innerHTML = renderBracketLeaderboardSkeleton();

  try {
    const rows = await getBracketLeaderboard();
    target.innerHTML = renderBracketLeaderboard(rows);
  } catch (err) {
    console.error('[Bracket] Failed to load leaderboard:', err);
    target.innerHTML = `
      <div class="bp-leaderboard-wrap">
        <div class="bp-leaderboard-card bp-leaderboard-error">
          <div class="bp-empty-icon">⚠️</div>
          <h3>Leaderboard failed to load</h3>
          <p>${escapeHtml(err.message || 'Please check the bracket_leaderboard view and RLS policy.')}</p>
          <button class="bp-refresh-btn" onclick="renderBracketLeaderboardIntoView()">Try Again</button>
        </div>
      </div>
    `;
  }
}

function renderBracketLeaderboardLockedState() {
  return `
    <div class="bp-leaderboard-wrap">
      <div class="bp-leaderboard-card bp-leaderboard-empty">
        <div class="bp-empty-icon">🔒</div>
        <h3>Leaderboard hidden before lock</h3>
        <p>Bracket picks stay private until the deadline.</p>
      </div>
    </div>
  `;
}

function renderBracketLeaderboard(rows) {
  const currentUserId = getCurrentUserIdSafe();
  const safeRows = Array.isArray(rows) ? rows : [];
  const sortedRows = safeRows.slice().sort((a, b) => getLeaderboardTotalPoints(b) - getLeaderboardTotalPoints(a));
  const myIndex = currentUserId ? sortedRows.findIndex(row => getLeaderboardUserId(row) === currentUserId) : -1;
  const myRow = myIndex >= 0 ? sortedRows[myIndex] : null;
  const myRank = myRow ? getLeaderboardRank(myRow, myIndex) : null;
  const top3 = sortedRows.slice(0, 3);
  const listRows = sortedRows.slice(3);
  const podiumSlot = (row, index) => {
    if (!row) return `<div class="bp-podium-slot empty"></div>`;
    const rank = getLeaderboardRank(row, index);
    const name = getLeaderboardPlayerName(row);
    const points = getLeaderboardTotalPoints(row);
    const initials = bpEscapeHtml(String(name).split(/\s+/).map(p=>p[0]).join('').slice(0,2).toUpperCase() || 'P');
    return `<div class="bp-podium-slot rank-${rank}">
      <div class="bp-podium-badge">${rank}</div>
      <div class="bp-podium-avatar">${initials}</div>
      <strong>${escapeHtml(name)}</strong>
      <span>${points} PTS</span>
    </div>`;
  };

  return `
    <div class="bp-leaderboard-wrap bp-leaderboard-fantasy">
      <div class="bp-leaderboard-hero">
        <div>
          <div class="bp-leaderboard-kicker">Separate competition</div>
          <h3>Bracket Leaderboard</h3>
          <p>Ranks here do not affect the Main League.</p>
        </div>
        <button class="bp-refresh-btn" onclick="renderBracketLeaderboardIntoView()">Refresh</button>
      </div>
      <div class="bp-lb-switch"><button class="active">My League</button><button>Global</button></div>
      ${top3.length ? `<div class="bp-podium">${podiumSlot(top3[1],1)}${podiumSlot(top3[0],0)}${podiumSlot(top3[2],2)}</div>` : ''}
      <div class="bp-leaderboard-card">
        ${listRows.length ? listRows.map((row, index) => renderBracketLeaderboardRow(row, index + 3, currentUserId)).join('') : sortedRows.length ? '' : `
          <div class="bp-leaderboard-empty"><div class="bp-empty-icon">🏆</div><h3>No leaderboard entries yet</h3><p>Paid submitted brackets will appear here after scoring begins.</p></div>`}
      </div>
      <div class="bp-my-rank-card bp-my-rank-bottom">
        <div><span>Your Rank</span><strong>${myRow ? `${myRank} / ${sortedRows.length}` : `— / ${sortedRows.length || 0}`}</strong></div>
        <div><span>Your Points</span><strong>${myRow ? getLeaderboardTotalPoints(myRow) : 0} PTS</strong></div>
      </div>
      ${!myRow && sortedRows.length ? `<div class="bp-public-note">You did not submit a bracket, but the public leaderboard is now visible.</div>` : ''}
    </div>
  `;
}

function renderBracketLeaderboardRow(row, index, currentUserId) {
  const rank = getLeaderboardRank(row, index);
  const isMe = currentUserId && getLeaderboardUserId(row) === currentUserId;
  const name = getLeaderboardPlayerName(row);
  const champion = getLeaderboardChampion(row);
  const championFlag = getLeaderboardChampionFlag(row);
  const correct = getLeaderboardCorrectPicks(row);
  const points = getLeaderboardTotalPoints(row);

  return `
    <div class="bp-lb-row ${isMe ? 'me' : ''}">
      <div class="bp-lb-rank ${rank <= 3 ? 'podium' : ''}">${getRankMedal(rank)}</div>
      <div class="bp-lb-main">
        <div class="bp-lb-name">${escapeHtml(name)} ${isMe ? '<span class="bp-lb-you">You</span>' : ''}</div>
        <div class="bp-lb-champion"><span>${escapeHtml(championFlag)}</span> Champion: ${escapeHtml(champion)}</div>
      </div>
      <div class="bp-lb-meta">
        <strong>${points}</strong>
        <span>${correct} correct</span>
      </div>
    </div>
  `;
}

