async function adminOpenBracket() {
  await updateBracketStatus('open');
  await refreshBracketSettingsAndRender('admin-open');
}

async function adminLockBracket() {
  console.log('[Bracket] Admin locking bracket...');
  try {
    await updateBracketStatus('locked');
    console.log('[Bracket] Status updated to locked');
    bracketState.settings = await getBracketSettings();
    bracketState.isLocked = isBracketLockedStatus(bracketState.settings?.status);
    if (isHiddenAdminPreviewMode()) bracketState.isLocked = false;
    setupBracketStatusListeners();
    setupHomeBracketMutationObserver();
    console.log('[Bracket] Refreshed state:', bracketState.settings?.status, bracketState.isLocked);
    await renderBracketCard();
    console.log('[Bracket] Card re-rendered');
  } catch (err) {
    console.error('[Bracket] Lock failed:', err);
    alert('Lock failed: ' + err.message);
  }
}

async function adminStartLive() {
  await updateBracketStatus('live');
  await refreshBracketSettingsAndRender('admin-live');
}

async function adminCompleteBracket() {
  await updateBracketStatus('completed');
  await refreshBracketSettingsAndRender('admin-complete');
}

