// Auto-boot the Home-tab suspense cover even if the main app forgets to call initBracketChallenge after reload.
(function bracketHomeCoverAutoBoot(){
  const boot = () => {
    try {
      setupBracketStatusListeners();
      setupHomeBracketMutationObserver();
      if (bracketState.settings) {
        applyHomeBracketStatusOverlay();
      } else {
        refreshBracketSettingsAndRender('auto-home-cover');
      }
    } catch (e) {
      console.warn('[Bracket] Home cover auto boot failed:', e);
    }
  };

  // Safety net: even if everything above hangs, never leave the card invisibly stuck.
  // After 1.5s, force bracket-status-ready so the card reveals whatever state it currently is in.
  const failSafeReveal = () => {
    if (!document.body.classList.contains('bracket-status-ready')) {
      document.body.classList.add('bracket-status-ready');
      console.warn('[Bracket] Forced bracket-status-ready by 1500ms safety timer.');
    }
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot, { once: true });
  } else {
    setTimeout(boot, 0);
  }
  window.addEventListener('load', () => setTimeout(boot, 250));
  setTimeout(failSafeReveal, 1500);
})();

